      "number": 2,
      "arFull": "اِنَّاۤ اَنْزَلْنَاۤ اِلَیْكَ الْكِتٰبَ بِالْحَقِّ فَاعْبُدِ اللّٰهَ مُخْلِصًا لَّهُ الدِّیْنَ ۟ؕ",
      "ur": "یقیناً ہم نے اس کتاب کو آپ کی طرف حق کے ساتھ[1] نازل فرمایا ہے پس آپ اللہ ہی کی عبادت کریں، اسی کے لئے دین کو خالص کرتے ہوئے.[2]",
      "en": "Indeed, We have sent down to you the Book, [O Muḥammad], in truth. So worship Allāh, [being] sincere to Him in religion.",
      "footnotesUr": "[1] یعنی اس میں توحید ورسالت، معاد اور احکام وفرائض کا جو اثبات کیا گیا ہے، وہ سب حق ہے اور انہی کے ماننے اور اختیار کرنے میں انسان کی نجات ہے۔\n[2] دین کے معنی یہاں عبادت اور اطاعت کے ہیں اور اخلاص کا مطلب ہے صرف اللہ کی رضا کی نیت سے نیک عمل کرنا۔ آیت، نیت کے وجوب اور اس کے اخلاص پر دلیل ہے۔ حدیث میں بھی اخلاص نیت کی اہمیت یہ کہہ کر واضح کر دی گئی ہے کہ إِنَّمَا الأَعْمَالُ بِالنِّيَّاتِ عملوں کا دارومدار نیتوں پر ہے یعنی جو عمل خیر اللہ کی رضا کے لئے کیا جائے گا، (بشرطیکہ وہ سنت کے مطابق ہو) وہ مقبول اور جس عمل میں کسی اور جذبے کی آمیزش ہوگی، وہ نامقبول ہوگا۔",
