      "arFull": "لَهُمْ مِّنْ فَوْقِهِمْ ظُلَلٌ مِّنَ النَّارِ وَمِنْ تَحْتِهِمْ ظُلَلٌ ؕ ذٰلِكَ یُخَوِّفُ اللّٰهُ بِهٖ عِبَادَهٗ ؕ یٰعِبَادِ فَاتَّقُوْنِ ۟",
      "ur": "انہیں نیچے اوپر سے آگ کے (شعلے مثل) سائبان (کے) ڈھانک رہے ہوں گے[1] ۔ یہی (عذاب) ہے جن سے اللہ تعالیٰ اپنے بندوں کو ڈرا رہا ہے[2]، اے میرے بندو! پس مجھ سے ڈرتے رہو.",
      "en": "They will have canopies [i.e., layers] of fire above them and below them, canopies. By that Allāh threatens [i.e., warns] His servants. O My servants, then fear Me.",
      "footnotesUr": "[1] ظُلَلٌ، ظُلَّةٌ کی جمع ہے، سایہ۔ یہاں اطباق النار مراد ہیں، یعنی ان کے اوپر نیچے آگ کے طبق ہوں گے، جو ان پر بھڑک رہے ہوں گے۔ (فتح القدیر)۔\n[2] یعنی یہی مذکور خسران مبین اور عذاب ظلل ہے جس سے اللہ تعالیٰ اپنے بندوں کو ڈراتا ہے تاکہ وہ اطاعت الٰہی کا راستہ اختیار کرکے اس انجام بد سے بچ جائیں۔",
