      "arFull": "لِیُكَفِّرَ اللّٰهُ عَنْهُمْ اَسْوَاَ الَّذِیْ عَمِلُوْا وَیَجْزِیَهُمْ اَجْرَهُمْ بِاَحْسَنِ الَّذِیْ كَانُوْا یَعْمَلُوْنَ ۟",
