      "arFull": "فَاَصَابَهُمْ سَیِّاٰتُ مَا كَسَبُوْا ؕ وَالَّذِیْنَ ظَلَمُوْا مِنْ هٰۤؤُلَآءِ سَیُصِیْبُهُمْ سَیِّاٰتُ مَا كَسَبُوْا ۙ وَمَا هُمْ بِمُعْجِزِیْنَ ۟",
      "ur": "پھر ان کی تمام برائیاں[1] ان پر آ پڑیں، اوران میں سے بھی جو گناه گار ہیں ان کی کی ہوئی برائیاں بھی اب ان پر آ پڑیں گی، یہ (ہمیں) ہرا دینے والے نہیں.[2]",
      "en": "And the evil consequences of what they earned struck them. And those who have wronged of these [people] will be struck [i.e., afflicted] by the evil consequences of what they earned; and they will not cause failure.[1353]",
      "footnotesUr": "[1] برائیوں سے مراد ان کی برائیوں کی جزا ہے، ان کو مشاکلﺖ کے اعتبار سے سیئات کہا گیا ہے، ورنہ برائی کی جزابرائی نہیں ہے۔ جیسے وَجَزَاءُ سَيِّئَةٍ سَيِّئَةٌ مِثْلُهَا میں ہے۔ (فتح القدیر)۔\n[2] یہ کفارمکہ کو تنبیہ ہے۔ چنانچہ ایساہی ہوا، یہ بھی گزشتہ قوموں کی طرح قحط، قتل و اسارت وغیرہ سے دوچار ہوئے، اللہ کی طرف سے آئےہوئے ان عذابوں کویہ روک نہیں سکے۔",
