      "en": "Allāh is the Creator of all things, and He is, over all things, Disposer of affairs.",
      "footnotesUr": "[1] یعنی ہر چیز کا خالق بھی وہی ہے اورمالک بھی وہی،وہ جس طرح چاہے، تصرف اور تدبیر کرے۔ ہر چیز اس کے ماتحت اور زیر تصرف ہے۔ کسی کو سرتابی یا انکار کی مجال نہیں۔ وکیل، بمعنی محافظ اور مدبر۔ ہر چیز اس کے سپرد ہے اوروہ بغیرکسی کی مشارکت کے ان کی حفاطت اور تدبیرکر رہاہے۔",
